create function archiv_dokument_klassifikation_volltext_nachher() returns trigger language plpgsql
set search_path from current as $$
declare
    dokument_id uuid;
begin
    if tg_op = 'UPDATE' and old.dokument_id is distinct from new.dokument_id then
        update dokument d set volltext_tsv = archiv_dokument_volltext_tsv(
            d.id, d.titel, d.partner_name, d.tags, d.volltext, d.dateiname)
        where d.id = old.dokument_id;
    end if;
    if tg_op = 'DELETE' then
        dokument_id := old.dokument_id;
    else
        dokument_id := new.dokument_id;
    end if;
    update dokument d set volltext_tsv = archiv_dokument_volltext_tsv(
        d.id, d.titel, d.partner_name, d.tags, d.volltext, d.dateiname)
    where d.id = dokument_id;
    return null;
end
$$
